#!/usr/bin/env python3
# Fill a QMD freshly generated by qproj::use_qmd() with the RecWaterVirome
# chunk layout: keep the template's params and setup chunks (UUID, clean =
# FALSE, path bindings) and its "Files written" chunk; replace the YAML
# header, the packages chunk and the example Tasks section.
# Authors (display order): Jinlong Ru, Cunli Pan
# Usage: fill-qmd.py <qmd> <subtitle> <packages-file> <body-file>
import sys, re, json
qmd, subtitle, pkg_file, body_file = sys.argv[1:5]
s = open(qmd, encoding="utf-8").read()
name = re.search(r'name: "([^"]+)"', s).group(1)
if "step-guard" in s:
    sys.exit("already filled: " + qmd)
header = f'''---
title: "{name}"
subtitle: {json.dumps(subtitle, ensure_ascii=False)}
author:
  - name: Jinlong Ru
    orcid: "0000-0002-6757-6018"
  - name: Cunli Pan
    orcid: "0000-0002-2595-7533"
date: today
params:
  name: "{name}"
---
'''
s = re.sub(r'\A---\n.*?\n---\n', header, s, count=1, flags=re.S)
pk = open(pkg_file, encoding="utf-8").read().rstrip("\n")
s = re.sub(r'```\{r\}\n#\| label: packages\n.*?\n```\n', pk + "\n", s, count=1, flags=re.S)
guard = '''
```{r}
#| label: step-guard
#| cache: false
# Checks params$name, path_target() and here() against config/workflow.yml
# New outputs are staged; previous successful outputs remain until publication.
step <- rwv_step_begin(params$name, path_target)
path_target <- step$path_target
```

```{r}
#| label: report-presentation
#| include: false
rwv_report_setup(step)
```

<!-- RWV_REPORT_SUMMARY_POSITION -->

<details class="rwv-analysis-details">
<summary>Analysis steps, methods and full verification</summary>
'''
body = open(body_file, encoding="utf-8").read().rstrip("\n")
i = s.index("## Tasks")
j = s.index("## Files written")
# The supplied scientific body must publish its outputs with rwv_step_finish.
footer = '\n\n</details>\n\n<details class="rwv-file-details">\n<summary>All output files</summary>\n\n```{r}\n#| label: list-files-target\nrwv_report_files(step, outputs)\n```\n\n</details>\n\n```{r}\n#| label: report-summary\n#| results: asis\nrwv_report_complete(step, outputs)\ncat(rwv_report_summary(step))\n```\n'
s = s[:i].rstrip("\n") + "\n" + guard + "\n" + body + footer
open(qmd, "w", encoding="utf-8").write(s)
print("filled", qmd)
